  var BN_MONTHS = [
    'জানুয়ারি', 'ফেব্রুয়ারি', 'মার্চ', 'এপ্রিল', 'মে', 'জুন',
    'জুলাই', 'আগস্ট', 'সেপ্টেম্বর', 'অক্টোবর', 'নভেম্বর', 'ডিসেম্বর'
  ];

  function toBnNum(val) {
    return String(val).replace(/\d/g, function (d) { return BN_DIGITS[Number(d)]; });
  }

  function todayBnString() {
    var d = new Date();
    return toBnNum(d.getDate()) + ' ' + BN_MONTHS[d.getMonth()] + ' ' + toBnNum(d.getFullYear());
  }

  function escapeHtml(str) {
    return String(str || '')
      .replace(/&/g, '&amp;')
      .replace(/</g, '&lt;')
      .replace(/>/g, '&gt;')
      .replace(/"/g, '&quot;');
  }

  function uid(prefix) {
    var rnd = Math.random().toString(36).slice(2, 9);
    return (prefix || 'pc') + '_' + Date.now().toString(36) + '_' + rnd;
  }

  function notify(msg) {
    if (window.TechHatImageUtils && window.TechHatImageUtils.showToast) {
      window.TechHatImageUtils.showToast(msg);
      return;
    }
    if (window.TechHatToast) {
      window.TechHatToast(msg);
      return;
    }
    var t = document.getElementById('toast');
    if (t) {
      t.textContent = msg;
      t.hidden = false;
      clearTimeout(notify._tid);
      notify._tid = setTimeout(function () { t.hidden = true; }, 2600);
    }
  }

  function formatTimeShortBn(ts) {
    if (!ts) return '';
    var d = new Date(ts);
    return toBnNum(d.getDate()) + ' ' + BN_MONTHS[d.getMonth()].slice(0, 5) + ' • ' +
      toBnNum(('0' + d.getHours()).slice(-2)) + ':' + toBnNum(('0' + d.getMinutes()).slice(-2));
  }

