    var baseX = customBoxW > 80 ? (x + (maxWidth - effMaxW) / 2) : x;

    var extraDelta = (!opts.noHit && hitKey !== 'headline') ? (getElFontDelta(hitKey) * U) : 0;
    var maxH = userResized ? 99999 : (opts.maxHeight || 9999);
    var sz = Math.max(10, Math.round((baseFontSize + extraDelta) * (1 + (portBoost - 1) * 0.55)));
    var minSz = userResized ? sz : Math.min(sz, opts.minSize || Math.max(8, Math.round(sz * 0.54)));
