    var U = Math.min(state.width || 1080, (state.height || 1080) * 1.28) / 1080;
    var portBoost = getPortBoost();
    var baseScaled = Math.min(Math.round(38 * U), Math.max(Math.round(30 * U), Math.round(fontSize * 1.44)));
    var fSz = Math.max(14, Math.round(baseScaled * portBoost + getElFontDelta(hitKey) * U));
