        kind: 'text',
        field: hitKey === 'detail' ? 'detail' : 'tagline',
        labelBn: hitKey === 'detail' ? tr('বিস্তারিত তথ্য', 'Details') : tr('সাব-হেডলাইন', 'Subheading'),
        x: drawX - 4,
        y: drawY - 4,
        w: effMaxW + 8,
        h: totalH + 8,
        textBoxX: drawX,
        textBoxY: drawY,
        textBoxW: effMaxW,
        renderFontPx: fSz,
        renderLineH: lineH,
        renderFontFamily: fam,
        renderWeight: weight,
        renderItalic: isItalic,
        renderColor: effColor,
        renderHiColor: effHiCol,
        renderUseMarker: hiMode === 'marker',
        renderMarkerFill: effHiCol,
        fontSize: Math.round(fSz / (U * portBoost)),
        align: effAlign,
        rotation: rot
